<template><div class="admin-applications-page"><AdminApplicationsTabs active="inductions"/><DemoIdentitySwitcher/><div v-if="identity.role!=='admin'" class="applications-queue applications-state"><strong>Admin demo view required</strong><p>Reviewers cannot access induction schedules, attendees, or meeting controls.</p></div><template v-else>
<header class="applications-page-header"><div><h1>Inductions</h1><p>Calendar and operational schedule for fictional induction bookings.</p></div><span class="demo-data-badge">Demo bookings</span></header>
<section class="application-summary-grid induction-summary" aria-label="Induction summary"><article v-for="x in summary" :key="x.label"><strong>{{x.count}}</strong><span>{{x.label}}</span></article></section>
<form class="application-filters induction-filters" @submit.prevent><select v-model="filters.state" aria-label="Filter induction status"><option value="all">All inductions</option><option value="upcoming">Upcoming</option><option value="today">Today</option><option value="needs-staff">Needs staff</option><option value="admin-attending">Admin attending</option><option value="paused">Paused</option><option value="cancelled">Cancelled</option><option value="completed">Completed</option></select><select v-model="filters.staff" aria-label="Assigned staff member"><option value="">All staff</option><option v-for="s in staffOptions" :key="s">{{s}}</option></select><button type="button" @click="resetFilters">Reset filters</button></form>
<section class="application-panel induction-calendar" aria-labelledby="calendar-title"><header><div><h2 id="calendar-title">Calendar</h2><p>Display time zone: <strong>{{displayTimeZone}}</strong>. Original record time zones are preserved.</p></div><div class="calendar-controls"><button type="button" aria-label="Previous month" @click="moveMonth(-1)">← Previous</button><button type="button" @click="goToday">Today</button><button type="button" aria-label="Next month" @click="moveMonth(1)">Next →</button><strong>{{monthLabel}}</strong></div></header><div class="calendar-grid" role="grid" :aria-label="monthLabel"><span v-for="d in weekdays" :key="d" role="columnheader">{{d}}</span><div v-for="d in calendarDays" :key="d.key" role="gridcell" :class="{muted:!d.current,selected:filters.date===d.iso}"><button v-if="d.events.length" type="button" class="calendar-date" :aria-label="`Show ${d.events.length} inductions on ${formatDay(d.date)}`" @click="focusDate(d.iso)">{{d.number}}</button><span v-else class="calendar-date">{{d.number}}</span><button v-for="e in d.events" :key="e.id" type="button" class="calendar-event" :aria-label="`${e.applicantName}, ${e.startTime}, ${e.status}`" @click="selectEvent(e)"><strong>{{e.startTime}} {{e.applicantName}}</strong><small>{{e.assignedStaff==='Unassigned'?'Needs staff':e.assignedStaff}} · {{e.status}}<template v-if="e.adminAttendees.length"> · Admin attending</template></small></button></div></div><div class="calendar-agenda" aria-label="Compact induction agenda"><article v-for="x in scheduled" :key="x.id"><button type="button" @click="selectEvent(x)"><strong>{{formatDate(x.date)}} · {{x.startTime}}</strong><span>{{x.applicantName}} · {{x.status}}</span><small>{{x.assignedStaff==='Unassigned'?'Needs staff':x.assignedStaff}}</small></button></article></div></section>
<section class="application-panel"><h2>Schedule table</h2><div class="applications-table-scroll"><table class="applications-table induction-table"><thead><tr><th>Date and time</th><th>Applicant</th><th>Staff and attendees</th><th>Acceptance</th><th>Status</th><th>Meeting</th><th>Actions</th></tr></thead><tbody><tr v-for="x in inductions" :key="x.id"><td><strong>{{formatDate(x.date)}}</strong><small>{{x.startTime}}–{{x.endTime}} · {{x.timeZone}}</small></td><td><strong>{{x.applicantName}}</strong><small>{{x.applicationReference}} · {{x.pathway}}</small></td><td>{{x.assignedStaff}}<small>Admin: {{x.adminAttendees.join(', ')||'None'}}</small></td><td>{{x.acceptanceOrigin}}</td><td>{{x.status}}</td><td>{{x.meetingState}}</td><td><div class="table-actions"><RouterLink :to="{name:'AdminInductionDetail',params:{inductionId:x.id}}">View induction</RouterLink><RouterLink v-if="x.applicationId" :to="{name:'AdminApplicationDetail',params:{applicationId:x.applicationId}}">View application</RouterLink><button type="button" @click="attend(x.id)">Mark attending</button><select :value="x.assignedStaff" :aria-label="`Reassign ${x.applicantName}`" @change="reassign(x.id,$event.target.value)"><option v-for="s in staffOptions" :key="s">{{s}}</option></select><button type="button" @click="openStatus(x,'paused')">Pause</button><button type="button" @click="openStatus(x,'cancelled')">Cancel</button></div></td></tr><tr v-if="!inductions.length"><td colspan="7">No inductions match these shared filters.</td></tr></tbody></table></div></section>
<div v-if="selected" class="event-summary" role="dialog" aria-modal="true" aria-labelledby="event-summary-title" @keydown.esc="selected=null"><div class="application-panel"><h2 id="event-summary-title">{{selected.applicantName}}</h2><p>{{formatDate(selected.date)}} · {{selected.startTime}}–{{selected.endTime}} {{selected.timeZone}}</p><p>{{selected.assignedStaff}} · {{selected.status}}</p><div><RouterLink class="application-action-link" :to="{name:'AdminInductionDetail',params:{inductionId:selected.id}}">View induction</RouterLink><button type="button" @click="selected=null">Close</button></div></div></div><DemoActionModal v-if="pending" :title="`${pending.status==='paused'?'Pause':'Cancel'} induction`" :warning="`This updates both views for ${pending.item.applicantName}.`" label="Internal reason" confirm-label="Confirm status change" @cancel="pending=null" @confirm="confirmStatus"/>
</template></div></template>
<script>import AdminApplicationsTabs from './components/AdminApplicationsTabs.vue';import DemoIdentitySwitcher from './components/DemoIdentitySwitcher.vue';import DemoActionModal from './components/DemoActionModal.vue';import{DEMO_STAFF,demoWorkflow,getDemoIdentity,getInductionSummary,listDemoInductions,markAdminAttending,reassignDemoInduction,setDemoInductionStatus}from'./applicationAdminData.js';const addDays=(d,n)=>{const x=new Date(d);x.setUTCDate(x.getUTCDate()+n);return x};export default{name:'AdminInductions',components:{AdminApplicationsTabs,DemoIdentitySwitcher,DemoActionModal},data:()=>({workflow:demoWorkflow,staffOptions:DEMO_STAFF,filters:{state:'all',staff:'',date:''},calendarBase:new Date('2026-08-01T12:00:00Z'),selected:null,pending:null,weekdays:['Mon','Tue','Wed','Thu','Fri','Sat','Sun']}),computed:{identity(){this.workflow.revision;return getDemoIdentity()},all(){this.workflow.revision;try{return this.identity.role==='admin'?listDemoInductions():[]}catch{return[]}},inductions(){this.workflow.revision;try{return this.identity.role==='admin'?listDemoInductions(this.filters):[]}catch{return[]}},scheduled(){return this.inductions.filter(x=>x.date!=='Not booked').sort((a,b)=>`${a.date}${a.startTime}`.localeCompare(`${b.date}${b.startTime}`))},summary(){return getInductionSummary(this.all,'2026-08-16')},displayTimeZone(){return Intl.DateTimeFormat().resolvedOptions().timeZone||'Europe/London'},monthLabel(){return this.calendarBase.toLocaleDateString('en-GB',{month:'long',year:'numeric',timeZone:'UTC'})},calendarDays(){const f=new Date(Date.UTC(this.calendarBase.getUTCFullYear(),this.calendarBase.getUTCMonth(),1)),o=(f.getUTCDay()+6)%7;return Array.from({length:42},(_,i)=>{const d=addDays(f,i-o),iso=d.toISOString().slice(0,10);return{key:iso,date:d,iso,number:d.getUTCDate(),current:d.getUTCMonth()===f.getUTCMonth(),events:this.scheduled.filter(e=>e.date===iso)}})}},methods:{moveMonth(n){this.calendarBase=new Date(Date.UTC(this.calendarBase.getUTCFullYear(),this.calendarBase.getUTCMonth()+n,1))},goToday(){this.calendarBase=new Date('2026-08-16T12:00:00Z');this.filters.date='2026-08-16'},focusDate(d){this.filters.date=this.filters.date===d?'':d},resetFilters(){this.filters={state:'all',staff:'',date:''}},selectEvent(x){this.selected=x;this.$nextTick(()=>document.querySelector('.event-summary button')?.focus())},attend(id){markAdminAttending(id)},reassign(id,s){reassignDemoInduction(id,s)},openStatus(item,status){this.pending={item,status}},confirmStatus(reason){setDemoInductionStatus(this.pending.item.id,this.pending.status,reason);this.pending=null},formatDate(v){return v==='Not booked'?'Not booked':new Intl.DateTimeFormat('en-GB',{dateStyle:'medium',timeZone:'UTC'}).format(new Date(`${v}T12:00:00Z`))},formatDay(v){return new Intl.DateTimeFormat('en-GB',{dateStyle:'full',timeZone:'UTC'}).format(v)}}};</script><style src="./AdminApplications.css"></style>
